pub fn to_variable_value(&self) -> ComputedPropertyValue {
    if let ValueInner::Universal(ref value) = self.v {
        return (**value).clone();
    }
    let css = self.to_css_string();
    let mut input = CSSParser::new(&css);
    let mut first = TokenSerializationType::Nothing;
    let mut last = TokenSerializationType::Nothing;
    while let Ok(token) = input.next_including_whitespace() {
        first.set_if_nothing(token.serialization_type());
        last = match token {
            // The parser skips nested blocks, including their closing token.
            Token::Function(_)
            | Token::ParenthesisBlock
            | Token::SquareBracketBlock
            | Token::CurlyBracketBlock => TokenSerializationType::Other,
            _ => token.serialization_type(),
        };
    }
    drop(input);
    ComputedPropertyValue::new(css, &self.url_data, first, last)
}

fn serialization_types(&self) -> (TokenSerializationType, TokenSerializationType) {
    let first_token_type = match self {
        Self::Length(_) | Self::Angle(_) | Self::Time(_) | Self::Resolution(_) => {
            TokenSerializationType::Dimension
        },
        Self::Number(_) | Self::Integer(_) => TokenSerializationType::Number,
        Self::Percentage(_) | Self::LengthPercentage(_) => TokenSerializationType::Percentage,
        Self::Color(_)
        | Self::Image(_)
        | Self::Url(_)
        | Self::TransformFunction(_)
        | Self::TransformList(_) => TokenSerializationType::Function,
        Self::CustomIdent(_) => TokenSerializationType::Ident,
        Self::String(_) => TokenSerializationType::Other,
    };
    let last_token_type = if first_token_type == TokenSerializationType::Function {
        TokenSerializationType::Other
    } else {
        first_token_type
    };
    (first_token_type, last_token_type)
}

fn serialization_types(&self) -> (TokenSerializationType, TokenSerializationType) {
    match &self.v {
        ValueInner::Component(component) => component.serialization_types(),
        ValueInner::Universal(_) => unreachable!(),
        ValueInner::List(list) => list
            .components
            .first()
            .map_or(Default::default(), |f| f.serialization_types()),
    }
}

pub fn to_variable_value(&self) -> ComputedPropertyValue {
    if let ValueInner::Universal(ref value) = self.v {
        return (**value).clone();
    }
    let serialization_types = self.serialization_types();
    ComputedPropertyValue::new(
        self.to_css_string(),
        &self.url_data,
        serialization_types.0,
        serialization_types.1,
    )
}

pub fn next_including_whitespace(&mut self) -> Result<&Token<'i>, BasicParseError> {
    while let Token::Comment(..) = self.next_including_whitespace_and_comments()? {
        // Keep going
    }
    Ok(&self.cached_token.token)
}

pub fn next_including_whitespace_and_comments(
    &mut self,
) -> Result<&Token<'i>, BasicParseError> {
    self.skip_block_at_start();

    if self.next_byte_before_delimiter().is_none() {
        return Err(BasicParseError::new(BasicParseErrorKind::EndOfInput));
    }

    let token_start_position = self.position();
    let using_cached_token = self.cached_token.start_position == token_start_position;
    if using_cached_token {
        self.state = self.cached_token.end_state.clone();
    } else {
        let new_token = self.next_unchecked();
        self.cached_token = CachedToken {
            token: new_token,
            start_position: token_start_position,
            end_state: self.state.clone(),
        };
    }

    Ok(&self.cached_token.token)
}

pub(crate) fn consume_until_end_of_block(&mut self, block_type: BlockType) {
    let mut stack = SmallVec::<[BlockType; 16]>::new();
    stack.push(block_type);

    // FIXME: have a special-purpose tokenizer method for this that does less work.
    while !self.is_eof() {
        let token = self.next_unchecked();
        if let Some(nested_block_type) = self.state.take_at_start_of() {
            stack.push(nested_block_type);
            continue;
        }
        if let Some(b) = BlockType::closing(&token) {
            if *stack.last().unwrap() == b {
                stack.pop();
                if stack.is_empty() {
                    return;
                }
            }
        }
    }
}

pub fn set_if_nothing(&mut self, new_value: TokenSerializationType) {
    if matches!(self, TokenSerializationType::Nothing) {
        *self = new_value
    }
}

pub(crate) fn skip_block_at_start(&mut self) {
    if let Some(block_type) = self.state.take_at_start_of() {
        self.consume_until_end_of_block(block_type);
    }
}
